// Dropbox Sign (formerly HelloSign) on the person's API key: every operation of its v3 API. actions.json is generated by
// `bun scripts/openapi-actions.ts dropbox_sign`; events start automations through the account's callback (triggers.ts).
import { AppFile } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "Dropbox Sign",
  base: "https://api.hellosign.com/v3",
  tokenHelp: "app.hellosign.com/home/myAccount#api",
  // the key is the user name of basic auth, with no password
  auth: (key) => ({ Authorization: `Basic ${Buffer.from(`${key}:`).toString("base64")}` }),
};

const EXT: Record<string, string> = { "application/pdf": ".pdf", "application/zip": ".zip" };

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
// Calls that take documents go as JSON unless a file is given; then as multipart, the only way a file can go
for (const a of (await Bun.file(file).json()).actions as { name: string; files?: string[]; send: Send }[]) {
  const action = actions[a.name]!;
  const run = action.run;
  action.run = async (input: Record<string, unknown>, key) => {
    const hasFile = a.files?.some((f) => input[f] !== undefined);
    const got = hasFile && a.send.body?.kind === "fields" ? await call(api, key, { ...a.send, body: { kind: "form", fields: a.send.body.fields } }, input) : await run(input, key);
    // downloads are named after the request's id: give them the extension too
    return got instanceof AppFile && !got.name.includes(".") ? new AppFile(`${got.name}${EXT[got.mimetype] ?? ""}`, got.mimetype, got.bytes) : got;
  };
}

export const dropbox_sign: OwnApp = {
  app: "dropbox_sign",
  name: "Dropbox Sign",
  logo: "/logos/dropbox_sign.svg",
  keyField: {
    label: "API key",
    help: "Dropbox Sign → Settings → API → API key: reveal or generate a key and copy it. Sending real signature requests through the API needs a paid Dropbox Sign API plan; with test_mode on, requests are free and not legally binding.",
    placeholder: "a1b2c3d4e5f6...",
  },
  async check(key) {
    const { account } = (await call(api, key, { method: "GET", path: "/account", query: [], headers: [] }, {})) as { account: { email_address?: string; account_id: string } };
    return account.email_address || account.account_id;
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(delivery, key),
    wanted,
  },
  actions,
};
